import { formatDistanceToNow } from "date-fns";

// Wraps date-fns for the app. The project moved from date-fns v2 to v4.
//
// v4 note: the "distance from a single date to the current time" helper is
// `formatDistanceToNow(date, { addSuffix: true })`. The v2-era two-argument
// spelling (`formatDistance(date, new Date(), ...)`) is the legacy form, so
// this wrapper now uses the now-centric API and normalizes/validates the
// input itself instead of relying on date-fns to reject an Invalid Date.
export function postedAt(dateLike) {
  const date = new Date(dateLike);

  if (!Number.isFinite(date.getTime())) {
    throw new RangeError(`postedAt: invalid date argument: ${dateLike}`);
  }

  return formatDistanceToNow(date, { addSuffix: true });
}

